import { describe, it, expect, afterEach } from 'vitest';
import { mkdtempSync, readFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';

/**
 * The opencode seam of fleet parallel-capacity autosizing, generated by
 * src/cli/hooks.ts.
 *
 * opencode never runs the .sh session-start hook, so the resident fleet's
 * parallel budget (engine level x proxy semaphore) reaches an opencode
 * session only through the plugin's session.created injection. The agent
 * then sizes its subagent fan-out to MAX_FANOUT; above it, streams only
 * queue (measured 2026-11-26 on the 5090 fleet: np=4 at a level-1
 * posture held a flat ~303 tok/s aggregate, identical to one stream).
 * These tests generate the plugin exactly as `uap hooks` ships it and pin
 * the injection: present, keyed, timeout-bounded, and fail-open.
 */
describe('opencode fleet-capacity plugin injection', () => {
  const dirs: string[] = [];
  afterEach(() => {
    for (const d of dirs) {
      try {
        rmSync(d, { recursive: true, force: true });
      } catch {
        /* ignore */
      }
    }
    dirs.length = 0;
  });

  const generate = async () => {
    const testDir = mkdtempSync(join(tmpdir(), `uap-oc-cap-${Date.now()}`));
    dirs.push(testDir);
    const { hooksCommand } = await import('../src/cli/hooks.js');
    await hooksCommand('install', { projectDir: testDir, target: 'opencode' });
    return testDir;
  };

  it('wires the fleet-capacity advisory into session.created (keyed instructions entry)', async () => {
    const testDir = await generate();
    const plugin = readFileSync(join(testDir, '.opencode', 'plugin', 'uap-session-hooks.ts'), 'utf-8');
    // The advisor call itself — same fail-open shell shape as loop-steer.
    expect(plugin).toContain('fleet-capacity');
    expect(plugin).toMatch(/await \$`\$\{tmo\} 10 fleet-capacity`|await \$`fleet-capacity`/);
    // The injection lands as a keyed V2 instructions entry (renders as a
    // <context key="..."> block), not a bare context push.
    expect(plugin).toContain('key: "uap-fleet-capacity"');
    expect(plugin).toContain('<uap-fleet-capacity>');
    expect(plugin).toContain('session.created');
    // Fail-open: a missing advisor on PATH must never break session start.
    expect(plugin).toContain('.nothrow()');
  });

  it('rides inside the session-start try block, after the loop-steer injection', async () => {
    const testDir = await generate();
    const plugin = readFileSync(join(testDir, '.opencode', 'plugin', 'uap-session-hooks.ts'), 'utf-8');
    const steerAt = plugin.indexOf('<uap-loop-steer>');
    const capAt = plugin.indexOf('<uap-fleet-capacity>');
    expect(steerAt).toBeGreaterThan(-1);
    expect(capAt).toBeGreaterThan(steerAt);
  });
});
